def setup_runtime(install=True):
    """Keep Kaggle's matching GPU torch/torchvision; pin small dependencies."""
    missing=[]
    for package, version in REQUIRED.items():
        try: current=importlib.metadata.version(package)
        except importlib.metadata.PackageNotFoundError: current=None
        if current != version: missing.append(f'{package}=={version}')
    if missing and install:
        loaded=[name for name in ('timm','sklearn','scipy') if name in sys.modules]
        if loaded:
            raise RuntimeError(f'Restart the notebook session or run this script in a fresh subprocess before installing dependencies; already loaded: {loaded}')
        subprocess.run([sys.executable, '-m', 'pip', 'install', '--quiet', '--no-deps',
                        *missing], check=True)
        importlib.invalidate_caches()
    elif missing:
        raise RuntimeError(f'Missing pinned dependencies: {missing}')
    global np, torch, timm, T, Image, stats, StratifiedShuffleSplit, f1_score
    import numpy as np
    import torch
    import timm
    import torchvision.transforms as T
    from PIL import Image
    from scipy import stats
    from sklearn.model_selection import StratifiedShuffleSplit
    from sklearn.metrics import f1_score
    from timm.layers import set_fused_attn
    set_fused_attn(False)
    torch.backends.cudnn.benchmark=False
    torch.backends.cudnn.deterministic=True
    torch.backends.cuda.matmul.allow_tf32=False
    torch.backends.cudnn.allow_tf32=False
    torch.use_deterministic_algorithms(True)


def sha(data): return hashlib.sha256(data).hexdigest()
def digest(value): return sha(json.dumps(value, sort_keys=True, separators=(',',':')).encode())
def file_sha(path):
    h=hashlib.sha256()
    with Path(path).open('rb') as f:
        for part in iter(lambda:f.read(1024*1024), b''): h.update(part)
    return h.hexdigest()


def write_json(path, value):
    path=Path(path); path.parent.mkdir(parents=True, exist_ok=True)
    temp=path.with_suffix(path.suffix+'.tmp')
    temp.write_text(json.dumps(value, indent=2, allow_nan=False), encoding='utf-8')
    temp.replace(path)


def write_csv(path, rows):
    path=Path(path);path.parent.mkdir(parents=True, exist_ok=True)
    if not rows: return
    with path.open('w', newline='', encoding='utf-8') as f:
        writer=csv.DictWriter(f, fieldnames=list(rows[0]));writer.writeheader();writer.writerows(rows)


def audit_payload():
    raw=zlib.decompress(base64.b64decode(AUDIT_B64))
    assert sha(raw)==AUDIT_SHA256, 'Embedded audit was modified'
    return json.loads(raw)


def seed_all(seed):
    random.seed(seed);np.random.seed(seed);torch.manual_seed(seed)
    if torch.cuda.is_available(): torch.cuda.manual_seed_all(seed)


class UnionFind:
    def __init__(self, values): self.parent={v:v for v in values}
    def find(self,x):
        while self.parent[x]!=x:
            self.parent[x]=self.parent[self.parent[x]];x=self.parent[x]
        return x
    def union(self,a,b):
        a,b=self.find(a),self.find(b)
        if a!=b: self.parent[max(a,b)]=min(a,b)


def rgb_hash(im):
    return sha(str(im.size).encode()+b'|RGB|'+im.tobytes())


def inventory(input_root, payload):
    """Deduplicate released fold copies by exact filename; verify all 755 bytes."""
    expected=payload['originals']; found={}
    # Expected names have no augmentation suffix. Exclude released augmentation trees.
    for parent, dirs, files in os.walk(input_root):
        dirs[:]=sorted(d for d in dirs if 'AUGMENT' not in d.upper() and 'FOLDS_AUG' not in d.upper())
        for name in sorted(files):
            if name in expected:
                path=Path(parent)/name
                if name not in found or str(path)<str(found[name]): found[name]=path
    assert set(found)==set(expected), f'Missing original photographs: {sorted(set(expected)-set(found))[:15]}'
    rows=[]
    for name in sorted(found):
        meta=expected[name]; path=found[name]; raw=file_sha(path)
        assert raw==meta['sha256'], f'Dataset version/content mismatch: {name}'
        with Image.open(path) as im: pixels=rgb_hash(im.convert('RGB'))
        rows.append(dict(filename=name, photo_id=Path(name).stem, path=str(path),
                         patient_id=meta['patient_id'], label=meta['label'],
                         source_sha256=raw, source_rgb_sha256=pixels))
    assert len(rows)==755 and len({r['patient_id'] for r in rows})==524
    return attach_clusters(rows, payload)


def attach_clusters(rows, payload):
    patients=UnionFind(r['patient_id'] for r in rows)
    photos=UnionFind(r['photo_id'] for r in rows)
    by_photo={r['photo_id']:r for r in rows}
    edges=[]
    for field in ('source_sha256','source_rgb_sha256'):
        first={}
        for r in rows:
            if r[field] in first: edges.append((first[r[field]],r['photo_id']))
            else: first[r[field]]=r['photo_id']
    edges+=list(map(tuple,payload['confirmed_cross_patient_photo_pairs']))
    edges+=list(map(tuple,payload['confirmed_within_patient_near_duplicate_pairs']))
    for a,b in edges:
        assert a in by_photo and b in by_photo, f'Audited photograph missing: {a}, {b}'
        assert by_photo[a]['label']==by_photo[b]['label'], 'Duplicate has conflicting labels'
        photos.union(a,b);patients.union(by_photo[a]['patient_id'],by_photo[b]['patient_id'])
    for r in rows:
        r['patient_cluster']=patients.find(r['patient_id'])
        r['photo_cluster']=photos.find(r['photo_id'])
    # Four verified cross-ID merges -> 520 components in this frozen release.
    assert len({r['patient_cluster'] for r in rows})==520, 'Unexpected extra exact-content merges; review audit'
    return rows


def split_and_plan(rows, seed):
    by_cluster={}
    for r in rows:
        key=r['patient_cluster']
        if key in by_cluster: assert by_cluster[key]==r['label']
        by_cluster[key]=r['label']
    clusters=sorted(by_cluster)
    splitter=StratifiedShuffleSplit(n_splits=1,test_size=.2,random_state=seed)
    tr,te=next(splitter.split(clusters,[by_cluster[c] for c in clusters]))
    train_groups={clusters[i] for i in tr}; test_groups={clusters[i] for i in te}
    assert len(train_groups)==416 and len(test_groups)==104 and not train_groups & test_groups
    train=sorted((r for r in rows if r['patient_cluster'] in train_groups),key=lambda r:r['filename'])
    test=sorted((r for r in rows if r['patient_cluster'] in test_groups),key=lambda r:r['filename'])
    clean=[dict(r, variant=v) for r in train for v in range(CONFIG['clean_copies'])]
    contaminated=copy.deepcopy(clean); diagnostic=[]; replacements=[]
    rng=np.random.default_rng(seed+10000)
    for cls in range(6):
        available=[i for i,e in enumerate(clean) if e['label']==cls and e['variant']>0]
        contaminants=[]
        for r in test:
            if r['label']!=cls: continue
            variants=rng.permutation(np.arange(1,11)).tolist()
            contaminants.extend(dict(r,variant=v) for v in variants[:8])
            diagnostic.extend(dict(r,variant=v) for v in variants[8:])
        assert len(available)>=len(contaminants), f'Insufficient same-class augmentation slots in class {cls}'
        selected=rng.choice(available,size=len(contaminants),replace=False).tolist()
        for slot,entry in zip(selected,contaminants):
            assert clean[slot]['variant']>0 and clean[slot]['label']==entry['label']
            contaminated[slot]=entry
            replacements.append(dict(slot=slot, removed_filename=clean[slot]['filename'],
                                     removed_variant=clean[slot]['variant'],
                                     inserted_filename=entry['filename'],inserted_variant=entry['variant'],label=cls))
    diagnostic.sort(key=lambda r:(r['filename'],r['variant']))
    plan=dict(seed=seed,train=train,test=test,clean=clean,contaminated=contaminated,
              diagnostic=diagnostic,replacements=sorted(replacements,key=lambda r:r['slot']))
    verify_plan(plan)
    return plan


def overlap_report(entries, test):
    report={}
    for field in ('patient_id','patient_cluster','photo_cluster','source_sha256','source_rgb_sha256'):
        report[field]=len({r[field] for r in entries}&{r[field] for r in test})
    report['content_and_patient_leak']=sum(report.values())
    return report


def verify_plan(plan):
    clean, dirty, test=plan['clean'],plan['contaminated'],plan['test']
    assert overlap_report(clean,test)['content_and_patient_leak']==0, 'Clean ancestry contamination'
    assert len(clean)==len(dirty)
    assert [r['label'] for r in clean]==[r['label'] for r in dirty], 'Batch-slot class order changed'
    assert [(i,r['filename']) for i,r in enumerate(clean) if r['variant']==0]==[(i,r['filename']) for i,r in enumerate(dirty) if r['variant']==0]
    assert len(plan['replacements'])==8*len(test)
    for row in test:
        assert sum(e['filename']==row['filename'] for e in dirty)==8
    assert set((r['filename'],r['variant']) for r in dirty).isdisjoint((r['filename'],r['variant']) for r in plan['diagnostic'])
    # Both condition evaluators receive this one frozen ordered test list, never separate splits.
    test_a=tuple((r['filename'],r['source_sha256'],r['label']) for r in test)
    test_b=tuple((r['filename'],r['source_sha256'],r['label']) for r in plan['test'])
    assert test_a==test_b


def augmentation_seed(seed, entry):
    return int(sha(f"table5:{seed}:{entry['filename']}:{entry['variant']}".encode())[:8],16)


def transforms():
    aug=T.Compose([T.RandomRotation(30),T.RandomAffine(degrees=0,translate=(.1,.1),scale=(.8,1.2),shear=15),
                   T.ColorJitter(brightness=.15,contrast=.2,saturation=.15,hue=.1),T.Resize((128,128)),T.PILToTensor()])
    base=T.Compose([T.Resize((128,128)),T.PILToTensor()])
    return aug,base


def render_entry(entry, seed, aug, base):
    if entry['variant']>0: seed_all(augmentation_seed(seed,entry))
    with Image.open(entry['path']) as im:
        value=(aug if entry['variant'] else base)(im.convert('RGB'))
    assert value.dtype==torch.uint8 and tuple(value.shape)==(3,128,128)
    return value


def tensor_sha(tensor):
    return sha(tensor.detach().cpu().contiguous().numpy().tobytes())


def materialize(plan, folder):
    """Offline augmentation is deterministic per source+variant, shared entries exact."""
    aug,base=transforms(); seed=plan['seed']
    clean=torch.stack([render_entry(r,seed,aug,base) for r in plan['clean']])
    dirty=clean.clone()
    for replacement in plan['replacements']:
        i=replacement['slot'];dirty[i]=render_entry(plan['contaminated'][i],seed,aug,base)
    test=torch.stack([render_entry(dict(r,variant=0),seed,aug,base) for r in plan['test']])
    diagnostic=torch.stack([render_entry(r,seed,aug,base) for r in plan['diagnostic']])
    y=torch.tensor([r['label'] for r in plan['clean']],dtype=torch.long)
    yt=np.array([r['label'] for r in plan['test']])
    hashes={k:[tensor_sha(x) for x in v] for k,v in [('clean',clean),('contaminated',dirty),('test',test),('diagnostic',diagnostic)]}
    assert not set(hashes['clean']) & set(hashes['test']), 'Clean input tensor equals a test tensor'
    assert not set(hashes['contaminated']) & set(hashes['test']), 'Original test pixels were inserted directly'
    assert not set(hashes['contaminated']) & set(hashes['diagnostic']), 'Augmented diagnostic tensor in training'
    changed={x['slot'] for x in plan['replacements']}
    for i in range(len(clean)):
        if i not in changed: assert hashes['clean'][i]==hashes['contaminated'][i]
    for condition in CONDITIONS:
        records=[]
        for i,r in enumerate(plan[condition]):
            records.append(dict(slot=i,filename=r['filename'],variant=r['variant'],label=r['label'],
                                patient_id=r['patient_id'],patient_cluster=r['patient_cluster'],photo_cluster=r['photo_cluster'],
                                source_sha256=r['source_sha256'],source_rgb_sha256=r['source_rgb_sha256'],
                                augmentation_seed=augmentation_seed(seed,r) if r['variant'] else '',
                                input_uint8_sha256=hashes[condition][i],intentional_contaminant=i in changed if condition=='contaminated' else False))
        write_csv(folder/f'{condition}_training_ancestry.csv',records)
    for key,entries in [('test',plan['test']),('diagnostic',plan['diagnostic'])]:
        write_csv(folder/f'{key}_tensor_manifest.csv',[dict(filename=r['filename'],variant=r.get('variant',0),label=r['label'],patient_cluster=r['patient_cluster'],input_uint8_sha256=h) for r,h in zip(entries,hashes[key])])
    return dict(clean=clean,contaminated=dirty,test=test,diagnostic=diagnostic,y=y,yt=yt,hashes=hashes)


def state_sha(state):
    h=hashlib.sha256()
    for key,value in sorted(state.items()):
        value=value.detach().cpu().contiguous();h.update(key.encode());h.update(str(value.dtype).encode());h.update(str(tuple(value.shape)).encode());h.update(value.numpy().tobytes())
    return h.hexdigest()


def new_network():
    return timm.create_model(CONFIG['model'],pretrained=False,num_classes=6,img_size=128)


def fetch_pretrained():
    from huggingface_hub import hf_hub_download
    path=hf_hub_download(PRETRAINED['repo'],PRETRAINED['filename'],revision=PRETRAINED['revision'])
    assert file_sha(path)==PRETRAINED['sha256'], 'Pretrained weights hash mismatch'
    return path


def initial_state(seed, pretrained_path):
    from safetensors.torch import load_file
    seed_all(seed)
    model=new_network();weights=load_file(str(pretrained_path),device='cpu')
    # Adapt the original 224px/1000-class checkpoint to 128px/6 classes using timm's official filter.
    from timm.models.vision_transformer import checkpoint_filter_fn
    weights=checkpoint_filter_fn(weights,model,adapt_layer_scale=True)
    weights.pop('head.weight',None);weights.pop('head.bias',None)
    incompat=model.load_state_dict(weights,strict=False)
    assert set(incompat.missing_keys)=={'head.weight','head.bias'} and not incompat.unexpected_keys
    state={k:v.detach().cpu().clone() for k,v in model.state_dict().items()}
    del model;return state


def environment():
    names=['torch','torchvision','timm','numpy','scipy','scikit-learn','Pillow','safetensors','huggingface-hub']
    packages={p:importlib.metadata.version(p) for p in names}
    return dict(python=platform.python_version(),packages=packages,cuda=torch.version.cuda,
                cuda_device_count=torch.cuda.device_count(),
                cudnn=torch.backends.cudnn.version(),device=torch.cuda.get_device_name(0) if torch.cuda.is_available() else 'cpu')


def atomic_torch_save(value,path):
    temp=path.with_suffix('.tmp');torch.save(value,temp);temp.replace(path)
    write_json(path.with_suffix('.sha256.json'),dict(sha256=file_sha(path),bytes=path.stat().st_size))


def load_checkpoint(path):
    meta=json.loads(path.with_suffix('.sha256.json').read_text())
    assert path.stat().st_size==meta['bytes'] and file_sha(path)==meta['sha256'], f'Incomplete checkpoint {path}'
    return torch.load(path,map_location='cpu',weights_only=False)


def normalise(x,device): return x.to(device,non_blocking=True).float().div_(255.).sub_(.5).div_(.5)


def predict(model,images,device):
    model.eval();probs=[]
    with torch.inference_mode():
        for start in range(0,len(images),128):
            p=model(normalise(images[start:start+128],device)).softmax(1)
            assert torch.isfinite(p).all();probs.append(p.cpu().numpy())
    return np.concatenate(probs)


def train_condition(seed,condition,data,init,signature,folder,deadline,device):
    out=folder/condition;out.mkdir(exist_ok=True)
    result_path=out/'result.json'; npz=out/'predictions.npz'
    if result_path.exists():
        result=json.loads(result_path.read_text())
        assert result['signature']==signature and result['epochs_completed']==CONFIG['epochs']
        assert file_sha(npz)==result['predictions_sha256']
        return dict(np.load(npz,allow_pickle=False)),result
    model=new_network();model.load_state_dict(init,strict=True)
    assert state_sha(model.state_dict())==state_sha(init), 'Initial model differs between conditions'
    model.to(device);optimizer=torch.optim.Adam(model.parameters(),lr=CONFIG['lr'],weight_decay=0.)
    seed_all(seed);generator=torch.Generator().manual_seed(seed)
    loader=torch.utils.data.DataLoader(torch.utils.data.TensorDataset(data[condition],data['y']),
                batch_size=CONFIG['batch_size'],shuffle=True,generator=generator,num_workers=0,
                drop_last=False,pin_memory=device.type=='cuda')
    slots=(out/'resume_a.pt',out/'resume_b.pt');valid=[]
    for path in slots:
        if path.exists():
            try: checkpoint=load_checkpoint(path)
            except (AssertionError,OSError,ValueError,RuntimeError,EOFError,pickle.UnpicklingError) as exc:
                print(f'Ignoring damaged checkpoint {path.name}: {exc}',flush=True);continue
            assert checkpoint['signature']==signature, 'Checkpoint belongs to different data/code/runtime'
            valid.append(checkpoint)
    start_epoch=0;history=[];steps=0
    if valid:
        checkpoint=max(valid,key=lambda x:x['epoch'])
        model.load_state_dict(checkpoint['model']);optimizer.load_state_dict(checkpoint['optimizer'])
        start_epoch=checkpoint['epoch'];history=checkpoint['history'];steps=checkpoint['steps']
        random.setstate(checkpoint['python_rng']);np.random.set_state(checkpoint['numpy_rng'])
        torch.set_rng_state(checkpoint['torch_rng']);generator.set_state(checkpoint['loader_rng'])
        if device.type=='cuda': torch.cuda.set_rng_state_all(checkpoint['cuda_rng'])
        print(f'RESUME seed {seed} {condition} after epoch {start_epoch}',flush=True)
    def save(epoch):
        checkpoint=dict(signature=signature,epoch=epoch,model=model.state_dict(),optimizer=optimizer.state_dict(),
            history=history,steps=steps,python_rng=random.getstate(),numpy_rng=np.random.get_state(),
            torch_rng=torch.get_rng_state(),loader_rng=generator.get_state(),
            cuda_rng=torch.cuda.get_rng_state_all() if device.type=='cuda' else [])
        atomic_torch_save(checkpoint,slots[epoch%2])
        write_json(out/'status.json',dict(status='training',epoch=epoch,epochs=CONFIG['epochs'],steps=steps,signature=signature))
    if not valid: save(0)
    for epoch in range(start_epoch,CONFIG['epochs']):
        last=max([h['seconds'] for h in history[-3:]] or [180.])
        if time.monotonic()+last*1.4+240>deadline:
            write_json(out/'status.json',dict(status='paused',epoch=epoch,signature=signature))
            del model,optimizer;gc.collect()
            if device.type=='cuda':torch.cuda.empty_cache()
            return None,None
        t0=time.monotonic();model.train();total_loss=0.;seen=0
        for x,y in loader:
            x=normalise(x,device);y=y.to(device,non_blocking=True)
            optimizer.zero_grad(set_to_none=True)
            loss=torch.nn.functional.cross_entropy(model(x),y)
            assert torch.isfinite(loss), 'Nonfinite loss'
            loss.backward();optimizer.step();steps+=1
            total_loss+=float(loss.detach())*len(y);seen+=len(y)
        if device.type=='cuda':torch.cuda.synchronize()
        history.append(dict(epoch=epoch+1,loss=total_loss/seen,seconds=time.monotonic()-t0,steps=steps))
        save(epoch+1)
        print(f'seed {seed} {condition}: epoch {epoch+1}/{CONFIG["epochs"]}, loss {total_loss/seen:.5f}, {history[-1]["seconds"]:.1f}s',flush=True)
    assert steps==CONFIG['epochs']*math.ceil(len(data['y'])/CONFIG['batch_size'])
    probs=predict(model,data['test'],device);diag=predict(model,data['diagnostic'],device)
    np.savez_compressed(npz,original_probs=probs,diagnostic_probs=diag,labels=data['yt'])
    atomic_torch_save({k:v.detach().cpu() for k,v in model.state_dict().items()},out/'final_weights.pt')
    result=dict(signature=signature,epochs_completed=CONFIG['epochs'],optimizer_updates=steps,
                training_images=len(data['y']),initial_state_sha256=state_sha(init),
                predictions_sha256=file_sha(npz),final_state_sha256=state_sha(model.state_dict()))
    write_json(out/'history.json',history);write_json(result_path,result)
    write_json(out/'status.json',dict(status='complete',**result))
    del model,optimizer;gc.collect()
    if device.type=='cuda':torch.cuda.empty_cache()
    return dict(original_probs=probs,diagnostic_probs=diag,labels=data['yt']),result


def metrics(y,p):
    predicted=p.argmax(1)
    return dict(n=len(y),correct=int((predicted==y).sum()),accuracy=float((predicted==y).mean()),
                macro_f1=float(f1_score(y,predicted,labels=list(range(6)),average='macro',zero_division=0)))


def mcnemar(y,a,b,scope):
    ca,cb=np.asarray(a)==y,np.asarray(b)==y
    b01=int((~ca & cb).sum());b10=int((ca & ~cb).sum());n=b01+b10
    return dict(n_pairs=len(y),both_correct=int((ca & cb).sum()),both_wrong=int((~ca & ~cb).sum()),
                clean_wrong_contaminated_correct=b01,clean_correct_contaminated_wrong=b10,
                statistic_min_discordant=min(b01,b10),
                p_exact=float(stats.binomtest(b01,n,.5).pvalue) if n else 1.,interpretation=scope)


def cluster_predictions(test,probs):
    keys=sorted({r['patient_cluster'] for r in test});ys=[];ps=[]
    for key in keys:
        ids=[i for i,r in enumerate(test) if r['patient_cluster']==key]
        labels={test[i]['label'] for i in ids};assert len(labels)==1
        ys.append(labels.pop());ps.append(probs[ids].mean(0))
    return keys,np.array(ys),np.stack(ps)


def summarise_pair(plan,clean,dirty,folder):
    test=plan['test'];y=clean['labels'];assert np.array_equal(y,dirty['labels'])
    a,b=clean['original_probs'],dirty['original_probs']
    assert len(a)==len(b)==len(test)
    records=[]
    for i,r in enumerate(test):
        row=dict(seed=plan['seed'],test_order=i,filename=r['filename'],label=int(y[i]),
                 patient_id=r['patient_id'],patient_cluster=r['patient_cluster'],source_sha256=r['source_sha256'],
                 clean_pred=int(a[i].argmax()),contaminated_pred=int(b[i].argmax()),
                 clean_correct=int(a[i].argmax()==y[i]),contaminated_correct=int(b[i].argmax()==y[i]))
        row.update({f'{condition}_p{c}':float(p[i,c]) for condition,p in [('clean',a),('contaminated',b)] for c in range(6)})
        records.append(row)
    write_csv(folder/'shared_original_predictions.csv',records)
    keys,cy,ca=cluster_predictions(test,a);keys2,cy2,cb=cluster_predictions(test,b)
    assert keys==keys2 and np.array_equal(cy,cy2)
    cluster_rows=[dict(seed=plan['seed'],patient_cluster=k,label=int(cy[i]),clean_pred=int(ca[i].argmax()),contaminated_pred=int(cb[i].argmax())) for i,k in enumerate(keys)]
    write_csv(folder/'patient_cluster_predictions.csv',cluster_rows)
    # Cluster bootstrap preserves related images as a block for image-accuracy gap CIs.
    sums=np.array([[sum(int(b[i].argmax()==y[i])-int(a[i].argmax()==y[i]) for i,r in enumerate(test) if r['patient_cluster']==k),sum(r['patient_cluster']==k for r in test)] for k in keys])
    rng=np.random.default_rng(plan['seed']+20000);draw=rng.integers(len(keys),size=(CONFIG['cluster_bootstrap_replicates'],len(keys)))
    draws=sums[draw].sum(axis=1);boot=draws[:,0]/draws[:,1]*100
    result=dict(seed=plan['seed'],clean=metrics(y,a),contaminated=metrics(y,b),
                gap_percentage_points=float(((b.argmax(1)==y).mean()-(a.argmax(1)==y).mean())*100),
                macro_f1_gap=metrics(y,b)['macro_f1']-metrics(y,a)['macro_f1'],
                image_mcnemar=mcnemar(y,a.argmax(1),b.argmax(1),'Descriptive; multiple images per patient cluster violate image independence.'),
                patient_cluster_mcnemar=mcnemar(cy,ca.argmax(1),cb.argmax(1),'One probability-averaged prediction per merged patient cluster, per seed; conditional on fitted models and cluster-independence assumption.'),
                patient_cluster_clean=metrics(cy,ca),patient_cluster_contaminated=metrics(cy,cb),
                image_accuracy_gap_cluster_bootstrap_95_percentile=[float(v) for v in np.quantile(boot,[.025,.975])])
    dy=np.array([r['label'] for r in plan['diagnostic']])
    diagnostic_rows=[]
    for i,r in enumerate(plan['diagnostic']):
        diagnostic_rows.append(dict(seed=plan['seed'],filename=r['filename'],variant=r['variant'],label=int(dy[i]),patient_cluster=r['patient_cluster'],
                    clean_pred=int(clean['diagnostic_probs'][i].argmax()),contaminated_pred=int(dirty['diagnostic_probs'][i].argmax()),
                    clean_probabilities=json.dumps(clean['diagnostic_probs'][i].tolist()),contaminated_probabilities=json.dumps(dirty['diagnostic_probs'][i].tolist())))
    write_csv(folder/'diagnostic_augmented_predictions.csv',diagnostic_rows)
    result['secondary_augmented_diagnostic']={c:metrics(dy,p['diagnostic_probs']) for c,p in [('clean',clean),('contaminated',dirty)]}
    result['secondary_augmented_diagnostic']['scope']='Only two reserved variants per held-out photo; NOT the primary test and NOT a literal replication of old pipeline 1A.'
    write_json(folder/'paired_result.json',result)
    return result,records,cluster_rows


def describe(values):
    a=np.array(values,dtype=float);n=len(a);mean=float(a.mean());sd=float(a.std(ddof=1))
    half=float(stats.t.ppf(.975,n-1)*sd/math.sqrt(n))
    return dict(n_seeds=n,mean=mean,sd=sd,t95=[mean-half,mean+half])


def final_summary(pairs,records,cluster_records,out):
    assert sorted(p['seed'] for p in pairs)==SEEDS, 'All five paired seeds required'
    summary=dict(status='complete',schema=CONFIG['schema'],seeds=SEEDS,config=CONFIG)
    for condition in CONDITIONS:
        summary[condition]=dict(accuracy_percent=describe([p[condition]['accuracy']*100 for p in pairs]),
                               macro_f1=describe([p[condition]['macro_f1'] for p in pairs]))
    gaps=np.array([p['gap_percentage_points'] for p in pairs]);nonzero=gaps[gaps!=0]
    if float(gaps.std(ddof=1))==0: paired_p=1. if float(gaps.mean())==0 else None
    else: paired_p=float(stats.ttest_1samp(gaps,0).pvalue)
    summary['gap_percentage_points']=dict(**describe(gaps),per_seed=gaps.tolist(),
        paired_t_p=paired_p,exact_two_sided_sign_p=float(stats.binomtest(int((nonzero>0).sum()),len(nonzero),.5).pvalue) if len(nonzero) else 1.,
        paired_t_note='Undefined for identical nonzero gaps (zero variance); recorded as null.' if paired_p is None else 'Paired t-test conditional on model assumptions.',
        sign_nonzero_pairs=len(nonzero),macro_f1_gap=describe([p['macro_f1_gap'] for p in pairs]),
        interpretation='Seed-paired, conditional on this dataset; test clusters overlap across seeds. t inference is model-based; not five independent clinical cohorts.')
    y=np.array([r['label'] for r in records]);a=np.array([r['clean_pred'] for r in records]);b=np.array([r['contaminated_pred'] for r in records])
    summary['pooled_image_mcnemar_descriptive_only']=mcnemar(y,a,b,'DESCRIPTIVE ONLY: related photos and repeated test patients across seeds; pooled p-value is not valid population inference.')
    summary['unique_test_clusters_across_seeds']=len({r['patient_cluster'] for r in records})
    summary['per_seed_paired_statistics']=[dict(seed=p['seed'],image_mcnemar=p['image_mcnemar'],patient_cluster_mcnemar=p['patient_cluster_mcnemar'],cluster_bootstrap_ci=p['image_accuracy_gap_cluster_bootstrap_95_percentile']) for p in pairs]
    summary['scope']='Controlled contamination intervention modeled on augmented-pool splitting; not an exact reproduction of Pal et al.; zero overlap is relative to verified hashes and known audit map.'
    write_json(out/'summary.json',summary);write_csv(out/'all_shared_original_predictions.csv',records)
    write_csv(out/'all_patient_cluster_predictions.csv',cluster_records)
    per_seed=[dict(seed=p['seed'],n_test_photos=p['clean']['n'],n_test_clusters=p['patient_cluster_clean']['n'],
                  clean_accuracy_percent=p['clean']['accuracy']*100,contaminated_accuracy_percent=p['contaminated']['accuracy']*100,
                  clean_macro_f1=p['clean']['macro_f1'],contaminated_macro_f1=p['contaminated']['macro_f1'],
                  gap_percentage_points=p['gap_percentage_points'],patient_cluster_mcnemar_p=p['patient_cluster_mcnemar']['p_exact'],
                  image_mcnemar_p_descriptive=p['image_mcnemar']['p_exact']) for p in pairs]
    write_csv(out/'per_seed_results.csv',per_seed)
    table=[]
    for condition in CONDITIONS:
        acc=summary[condition]['accuracy_percent'];f1=summary[condition]['macro_f1']
        table.append(dict(condition=condition,accuracy_mean_percent=acc['mean'],accuracy_sd_percent=acc['sd'],accuracy_t95_lower=acc['t95'][0],accuracy_t95_upper=acc['t95'][1],macro_f1_mean=f1['mean'],macro_f1_sd=f1['sd']))
    write_csv(out/'table5_summary.csv',table)
    text=['# Replacement Table 5: controlled contamination ablation','',
          '| Condition | Original-test accuracy, mean ± SD | Macro F1, mean ± SD |',
          '| --- | --- | --- |']
    for r in table:text.append(f"| {r['condition'].title()} | {r['accuracy_mean_percent']:.2f} ± {r['accuracy_sd_percent']:.2f}% | {r['macro_f1_mean']:.4f} ± {r['macro_f1_sd']:.4f} |")
    g=summary['gap_percentage_points'];tp='undefined (zero variance)' if g['paired_t_p'] is None else f"{g['paired_t_p']:.6g}"
    text+=['',f"Contaminated minus clean: {g['mean']:.2f} percentage points; t-based 95% interval {g['t95'][0]:.2f} to {g['t95'][1]:.2f}; paired t p={tp}; exact two-sided sign p={g['exact_two_sided_sign_p']:.6g}.",'',
        'Both conditions use the identical original test photographs within each seed. Training count, class counts, original-training slots, initialization, batch-slot order and update budget are matched. Eight augmented relatives per test photograph replace same-class augmented training slots. This is an intentional contamination intervention, not a literal random augmented-pool split or an exact replication of Pal et al.',
        '',summary['gap_percentage_points']['interpretation'],
        'Image McNemar p-values, especially the pooled value, are descriptive because of clustered/repeated observations. Per-seed patient-cluster McNemar and cluster bootstrap are supplied separately. The augmented diagnostic is secondary.']
    (out/'table5_ready.md').write_text('\n'.join(text)+'\n',encoding='utf-8')
    return summary


def package_results(out):
    files=sorted(p for p in out.rglob('*') if p.is_file() and p.suffix not in ('.pt','.tmp') and p.name!='SHA256SUMS.txt')
    (out/'SHA256SUMS.txt').write_text(''.join(f'{file_sha(p)}  {p.relative_to(out).as_posix()}\n' for p in files),encoding='utf-8')
    target=out.parent/'Table5_replacement_results.zip'
    with zipfile.ZipFile(target,'w',compression=zipfile.ZIP_DEFLATED,compresslevel=6) as z:
        for p in files+[out/'SHA256SUMS.txt']:z.write(p,Path(out.name)/p.relative_to(out))
    return target


def main(argv=None):
    parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--input-root',default='/kaggle/input')
    parser.add_argument('--out',default='/kaggle/working/table5_replacement')
    parser.add_argument('--check-only',action='store_true')
    parser.add_argument('--resume-root',help='Path containing a full previous table5_replacement output; copied into a NEW empty output directory.')
    args=parser.parse_args(argv)
    setup_runtime();out=Path(args.out)
    if args.resume_root:
        import shutil
        source=Path(args.resume_root).resolve()
        assert source.is_dir() and source.name=='table5_replacement', 'Point resume-root at the full previous table5_replacement folder'
        assert not out.exists() or not any(out.iterdir()), 'Resume copy requires an empty output directory'
        assert source!=out.resolve();shutil.copytree(source,out,dirs_exist_ok=True)
    out.mkdir(parents=True,exist_ok=True)
    payload=audit_payload();write_json(out/'embedded_audit.json',payload)
    rows=inventory(args.input_root,payload)
    dataset_signature=digest([{k:v for k,v in r.items() if k!='path'} for r in rows])
    write_csv(out/'verified_original_inventory.csv',rows)
    plans=[split_and_plan(rows,s) for s in SEEDS]
    for p in plans:
        folder=out/f'seed_{p["seed"]}';folder.mkdir(exist_ok=True)
        manifest=[dict(r,role='train' if r in p['train'] else 'test') for r in rows]
        write_csv(folder/'split_manifest.csv',manifest);write_csv(folder/'contamination_replacements.csv',p['replacements'])
        report=dict(seed=p['seed'],clean=overlap_report(p['clean'],p['test']),contaminated=overlap_report(p['contaminated'],p['test']),
            n_train_clusters=416,n_test_clusters=104,n_train_originals=len(p['train']),n_test_originals=len(p['test']),training_pool_images=len(p['clean']),
            replaced_slots=len(p['replacements']),contamination_fraction=len(p['replacements'])/len(p['clean']),
            test_manifest_sha256=digest([{k:r[k] for k in ('filename','label','source_sha256')} for r in p['test']]),
            scope='Patient IDs, exact raw/RGB content, and confirmed audited duplicate map. Unknown duplicates are not certified absent.')
        write_json(folder/'preflight.json',report)
        print(f"PREFLIGHT PASS seed {p['seed']}: 416/104 clusters; {len(p['train'])}/{len(p['test'])} originals; {len(p['clean'])} training slots; clean content_and_patient_leak=0",flush=True)
    if args.check_only:
        print('ALL FIVE PREFLIGHTS PASSED. No model training performed.',flush=True);return
    assert torch.cuda.is_available(), 'Select GPU T4 before research training'
    device=torch.device('cuda:0');env=environment()
    source_path=Path(__file__) if '__file__' in globals() else None
    source_hash=file_sha(source_path) if source_path is not None and source_path.is_file() else IMPLEMENTATION_SHA256
    identity=dict(config=CONFIG,seeds=SEEDS,dataset_signature=dataset_signature,audit_sha256=AUDIT_SHA256,
                  implementation_sha256=source_hash,pretrained=PRETRAINED,environment=env)
    identity_path=out/'run_identity.json'
    if identity_path.exists():assert json.loads(identity_path.read_text())==identity, 'Run/data/code/runtime changed; preserve old outputs and use a fresh folder'
    write_json(identity_path,identity)
    if source_path is not None and source_path.is_file():
        (out/'reproduction_source.py').write_bytes(source_path.read_bytes())
    weights=fetch_pretrained()
    deadline=time.monotonic()+CONFIG['max_hours']*3600;pairs=[];all_records=[];all_clusters=[]
    for plan in plans:
        seed=plan['seed'];folder=out/f'seed_{seed}'
        verify_plan(plan);data=materialize(plan,folder);init=initial_state(seed,weights)
        init_hash=state_sha(init)
        signature=digest(dict(identity=identity,seed=seed,initial_state_sha256=init_hash,tensor_hashes=data['hashes']))
        atomic_torch_save(init,folder/'shared_initial_weights.pt')
        write_json(folder/'training_identity.json',dict(signature=signature,initial_state_sha256=init_hash,training_images=len(data['y']),steps_per_condition=CONFIG['epochs']*math.ceil(len(data['y'])/CONFIG['batch_size'])))
        results={};meta={}
        for condition in CONDITIONS:
            results[condition],meta[condition]=train_condition(seed,condition,data,init,signature,folder,deadline,device)
            if results[condition] is None:
                write_json(out/'RUN_STATUS.json',dict(status='paused',seed=seed,condition=condition,completed_paired_seeds=[p['seed'] for p in pairs]))
                zip_path=package_results(out)
                print(f'SAFELY PAUSED. Preserve FULL saved output for resume; small ZIP is not a checkpoint: {zip_path}',flush=True);return
        assert meta['clean']['initial_state_sha256']==meta['contaminated']['initial_state_sha256']==init_hash
        assert meta['clean']['optimizer_updates']==meta['contaminated']['optimizer_updates']
        pair,records,cluster_records=summarise_pair(plan,results['clean'],results['contaminated'],folder)
        pairs.append(pair);all_records+=records;all_clusters+=cluster_records
        print(f"PAIRED SEED COMPLETE {seed}: clean {pair['clean']['accuracy']*100:.2f}%, contaminated {pair['contaminated']['accuracy']*100:.2f}%, gap {pair['gap_percentage_points']:.2f} points",flush=True)
        del data,init,results;gc.collect();torch.cuda.empty_cache()
    summary=final_summary(pairs,all_records,all_clusters,out)
    write_json(out/'RUN_STATUS.json',dict(status='complete',paired_seeds=SEEDS,training_runs=10,epochs_per_run=100))
    zip_path=package_results(out)
    print(f'COMPLETE: replacement Table 5; all five paired seeds and ten 100-epoch runs.\nDownload {zip_path}',flush=True)
    print(json.dumps({k:summary[k] for k in ('clean','contaminated','gap_percentage_points')},indent=2),flush=True)


if __name__=='__main__': main([] if 'ipykernel' in sys.modules else None)
